import java.io.*;
import java.util.*;
public class TwentyFive {
    public static void main(String[] args) throws Exception {
        FastIO in = new FastIO();
        String s = in.next();
        int ans = 0;
        // Precompute all multiples of 25 up to 10^8-1
        java.util.ArrayList<String> multiples = new java.util.ArrayList<>();
        for (int i = 0; i < 100000000; i += 25) {
            multiples.add(Integer.toString(i));
        }
        for (String test : multiples) {
            if (test.length() != s.length()) continue;
            boolean works = true;
            int xDigit = -1;
            // Use a Map to track X consistency (though not needed)
            for (int j = 0; j < test.length(); j++) {
                char sc = s.charAt(j);
                char tc = test.charAt(j);
                if (sc == 'X') {
                    if (xDigit == -1) xDigit = tc;
                    else if (tc != xDigit) { works = false; break; }
                } else if (sc != '_' && sc != tc) {
                    works = false; break;
                }
            }
            if (works) ans++;
        }
        System.out.println(ans);
    }

    static class FastIO {
        BufferedReader br;
        StringTokenizer st;
        public FastIO() throws IOException {
            br = new BufferedReader(new InputStreamReader(System.in));
        }
        public String next() throws IOException {
            while (st == null || !st.hasMoreElements())
                st = new StringTokenizer(br.readLine());
            return st.nextToken();
        }
    }
}
